  "headline": "FDA's records trace our supply to a plant classified OAI 2252 days before the posting",
  "headline_cites": ["D12"],
  "sentences": [
    {
      "text": "FDA first posted the ropivacaine hydrochloride shortage on 2018-03-23 and it remains current as of 2026-10-21.",
      "cites": ["E44", "E40", "E41", "E42", "E43"]
    },
    {
      "text": "Fresenius Kabi USA, LLC is listed as a current shortage manufacturer with an initial posting date of 2018-03-23.",
      "cites": ["E41"]
    },
    {
      "text": "The label for Fresenius Kabi USA, LLC product names Fresenius Kabi USA, LLC as a registered plant with FEI 1450022.",
      "cites": ["E28"]
    },
    {
      "text": "FDA inspection 1123748 of Fresenius Kabi USA LLC ended 2020-05-18 and was classified OAI with the classification letter dated 2024-05-22.",
      "cites": ["E25"]
    },
    {
      "text": "FDA inspection 1174894 of Fresenius Kabi USA LLC ended 2022-06-30 and was classified OAI with the classification letter dated 2024-04-30.",
      "cites": ["E26"]
    },
    {
      "text": "FDA's OAI classification letter to Fresenius Kabi USA, LLC is dated 2024-05-22, 2252 days after FDA posted the shortage on 2018-03-23.",
      "cites": ["D12"]
    },
    {
      "text": "The approved alternate manufacturer is Anthea Pharma Private Limited with ROPIVACAINE HYDROCHLORIDE 5 mg/mL, approved by Jordan Hale, PharmD on 2026-06-15.",
      "cites": ["D14", "E45"]
    }
  ]
}
